# Fetch all pages of liked songs, albums, and playlists.
def fetch_all_pages(api_func, access_token):
    all_items = []
    page_index = 0
    while True:
        page = api_func(access_token=access_token, page_index=page_index, page_limit=20)
        if not page or len(page) == 0:
            break
        all_items.extend(page)
        if len(page) < 20:
            break
        page_index += 1
    return all_items

all_liked_songs = fetch_all_pages(apis.spotify.show_liked_songs, access_token)
all_liked_albums = fetch_all_pages(apis.spotify.show_liked_albums, access_token)
all_liked_playlists = fetch_all_pages(apis.spotify.show_liked_playlists, access_token)

print("Total liked songs:", len(all_liked_songs))
print("Total liked albums:", len(all_liked_albums))
print("Total liked playlists:", len(all_liked_playlists))

