def fetch_all_pages(api_func, access_token):
    all_items = []
    page_index = 0
    while True:
        page = api_func(access_token=access_token, page_index=page_index, page_limit=20)
        if not page or len(page) == 0:
            break
        all_items.extend(page)
        if len(page) < 20:
            break
        page_index += 1
    return all_items

